        frFR = "Classic Era et WoW Forever : les quêtes de donjon affichent le nom court coloré de l'instance dans le journal de quêtes, chez le donneur de quêtes et dans le suivi, et les infobulles de quête la ligne « Donjon : nom ».",
        esES = "Classic Era y WoW Forever: las misiones de mazmorra muestran el nombre corto coloreado de la instancia en el registro de misiones, en el dador de misiones y en el seguimiento, y los tooltips de misión la línea «Mazmorra: nombre»." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: NPCs mit einer Dungeonquest, die du jetzt annehmen kannst, tragen ein Dungeon-Symbol an Namensplakette und Ziel, eine Tooltipzeile und einen Punkt auf der Karte.",
        enUS = "Classic Era and WoW Forever: NPCs with a dungeon quest you can take right now show a dungeon icon on their nameplate and target frame, a tooltip line and a map pin.",
        frFR = "Classic Era et WoW Forever : les PNJ ayant une quête de donjon que vous pouvez prendre maintenant affichent une icône de donjon sur leur barre de nom et la cible, une ligne d'infobulle et un repère sur la carte.",
        esES = "Classic Era y WoW Forever: los PNJ con una misión de mazmorra que puedes aceptar ahora muestran un icono de mazmorra en su placa de nombre y en el objetivo, una línea en el tooltip y un punto en el mapa." },
      { kind = "new",
        deDE = "Dungeon-Runs: Bosse und Rare erscheinen mit kleinem 3D-Porträt im Run-Fenster, der Endboss groß im Kopf, der Live-Tracker zeigt den nächsten Boss (Classic Era und WoW Forever).",
        enUS = "Dungeon runs: bosses and rares show a small 3D portrait in the runs window, the final boss a large one in the header, and the live tracker shows the next boss (Classic Era and WoW Forever).",
        frFR = "Donjons : les boss et rares affichent un petit portrait 3D dans la fenêtre des runs, le boss final en grand dans l'en-tête, et le suivi en direct montre le prochain boss (Classic Era et WoW Forever).",
        esES = "Mazmorras: jefes y raros muestran un pequeño retrato 3D en la ventana de partidas, el jefe final uno grande en la cabecera y el seguimiento en vivo muestra el siguiente jefe (Classic Era y WoW Forever)." },
      { kind = "new",
        deDE = "Neue Statistik Beutewert: Wert deiner Beute (Auctionator-Preis, sonst Händlerpreis) und Gold/h inklusive Beute, auch als Spalte in der Session-Historie.",
        enUS = "New statistic Loot value: the value of your loot (Auctionator price, otherwise vendor price) and gold/h including loot, also as a column in the session history.",
        frFR = "Nouvelle statistique Valeur du butin : la valeur de votre butin (prix Auctionator, sinon prix du marchand) et l'or/h butin compris, aussi en colonne dans l'historique des sessions.",
        esES = "Nueva estadística Valor del botín: el valor de tu botín (precio de Auctionator, si no precio de vendedor) y oro/h con el botín incluido, también como columna en el historial de sesiones." },
      { kind = "new",
        deDE = "Historie: neuer Reiter Twinks zeigt alle Charaktere mit Ruhe-XP, Gold, /played und zuletzt gespielt, sortiert nach „Wer ist dran?“, und markiert lange nicht gespielte.",
        enUS = "History: new Alts tab lists all characters with rested XP, gold, /played and last played, sorted by \"who's next?\", and marks those not played for a long time.",
        frFR = "Historique : nouvel onglet Rerolls avec tous les personnages, XP de repos, or, /played et dernière partie, triés par « à qui le tour ? », et ceux pas joués depuis longtemps marqués.",
        esES = "Historial: nueva pestaña Alters con todos los personajes, XP de descanso, oro, /played y última partida, ordenados por «¿a quién le toca?», y marca los que llevan mucho sin jugar." },
      { kind = "new",
        deDE = "Dungeon-Runs: Die Laufzeit zählt ab der ersten Bewegung in der Instanz, Bestzeiten gelten je Flügel, und der Verlauf zeigt im Tooltip die Zeit bis zu jedem Boss.",
        enUS = "Dungeon runs: run time counts from your first movement inside the instance, best times are kept per wing, and the history tooltip shows the time to each boss.",
        frFR = "Donjons : le temps du run compte à partir de votre premier mouvement dans l'instance, les meilleurs temps sont gardés par aile et l'infobulle de l'historique affiche le temps jusqu'à chaque boss.",
        esES = "Mazmorras: el tiempo de la partida cuenta desde tu primer movimiento dentro de la instancia, los mejores tiempos se guardan por ala y el tooltip del historial muestra el tiempo hasta cada jefe." },
      { kind = "change",
        deDE = "Level-Up-Fenster: Bleibt stehen, bis du es anklickst; die Checkbox „Automatisch schließen“ im Fenster blendet es wieder von selbst aus.",
        enUS = "Level-up window: stays until you click it; the \"Close automatically\" checkbox in the window makes it fade out on its own again.",
        frFR = "Fenêtre de niveau supérieur : reste affichée jusqu'à ce que vous cliquiez dessus ; la case « Fermer automatiquement » dans la fenêtre la refait disparaître seule.",
